manialink.script:
#RequireContext CTmMlScriptIngame

#Include "TextLib" as TL

#Include "Libs/Nadeo/Layers2.Script.txt" as LibLayers

#Struct ScoreEntry {
	Integer Value;
	Text Login;
}

#Const C_MaxItems 8

#Setting S_ShowDebug False as _("Show debug HUD")

// Inlined lib: MyLib
Text Nice() {
	return TL::StripFormatting(AuthorNickName);
}

declare CMlLabel LabelCountdown;
declare CMlQuad QuadMapName;
declare CMlFrame DynamicFrame;
declare CMlEntry EntryInput;
declare Integer G_PreviousTime;
declare Text[] LogHistory = [];
declare Integer[Text] Counters = [];

***OnMapIntroEnd***
***
log("Intro ended");
***

Void Private_OnAnyClick(CMlControl _Control, Text _ControlId) {
	log("Clicked: " ^ _ControlId);
	if (_ControlId == "CustomId") {
		QuadMapName.Hide();
	}
}

Void Private_OnEntrySubmitted(CMlControl _Control, Text _ControlId) {
	log("Entry submitted: " ^ _ControlId);
	LabelCountdown.Value = EntryInput.Value;
}

Void Private_LogAllEvents(CMlScriptEvent _E) {
	log("raw event");
}

Void Private_Describe(CMlControl _Control) {
	if (_Control is CMlLabel) {
		declare Label = (_Control as CMlLabel);
		log(Label.Value);
	} else if (_Control is CMlQuad) {
		declare Quad = (_Control as CMlQuad);
		log(Quad.ImageUrl);
	}
	switchtype (_Control) {
		case CMlEntry: {
			declare Entry = (_Control as CMlEntry);
			log(Entry.Value);
		}
		case CMlTextEdit: {
			declare Edit = (_Control as CMlTextEdit);
			log(Edit.Value);
		}
		default: {
			log("other control");
		}
	}
}

Integer Private_Multiply(Integer _A, Integer _B) {
	return _A * _B;
}

main() {
	G_PreviousTime = -1;

	LabelCountdown = (Page.GetFirstChild("LabelCountdown") as CMlLabel);
	QuadMapName = (Page.GetFirstChild("CustomId") as CMlQuad);
	DynamicFrame = (Page.GetFirstChild("DynamicFrame") as CMlFrame);
	EntryInput = (Page.GetFirstChild("EntryInput") as CMlEntry);

	declare Integer MyVar for LocalUser;
	MyVar = 5;
	+++OnMapIntroEnd+++
	Nice();
	declare Scores = ["alpha" => 10, "beta" => 20];
	declare Names = ["Alpha", "Beta", "Gamma", "Omega"];
	foreach (N in Names) {
		log("Player: " ^ N);
	}
	declare Doubled = Private_Multiply(3, 4);
	while (True) {
		yield;
		foreach (Event in PendingEvents) {
			log("event received");
			Private_LogAllEvents(Event);
			switch (Event.Type) {
				case CMlScriptEvent::Type::MouseClick: {
					Private_OnAnyClick(Event.Control, Event.ControlId);
					switch (Event.Control) {
						case QuadMapName: {
							declare Control = Event.Control;
							declare ControlId = Event.ControlId;
							log("Clicked the quad " ^ ControlId ^ "!");
						}
					}
				}
				case CMlScriptEvent::Type::EntrySubmit: {
					Private_OnEntrySubmitted(Event.Control, Event.ControlId);
				}
				case CMlScriptEvent::Type::MenuNavigation: {
					declare Action = Event.MenuNavAction;
					if (Action == CMlScriptEvent::EMenuNavAction::Cancel) {
						log("Cancelled");
					}
				}
			}
		}
		Private_Describe(QuadMapName);
	}
}
